// Relocation Entry (R_Entry) specifies what needs patching
struct R_Entry {
    uintptr_t offset;   // Offset in the section to update
    uint8_t type;       // Type of adjustment (e.g., RELATIVE, JUMP_SLOT)
};

// Simulation of the Dynamic Loader/Linker process
void ApplyRelocations(R_Entry* reloc_table, uintptr_t LoadBase) {
    for (R_Entry entry : reloc_table) {
        uintptr_t* TargetAddr = LoadBase + entry.offset;

        // Formula for absolute patching (e.g., R_X86_64_RELATIVE):
        // (Relative Value + Load Base) -> Absolute Address
        *TargetAddr = *TargetAddr + LoadBase;
    }
}

// Result: All relative addresses are converted to absolute
// based on the final memory location (LoadBase).
